function norm(s){return normalizePokemonText(s)}
function pokemonMatches(query){return findPokemonMatches(searchRows(),query)}
function matchText(text,k){const t=norm(text);return D.master[k].map(x=>x[0]).filter(n=>t.includes(norm(n))).sort((a,b)=>b.length-a.length).filter((n,i,a)=>!a.slice(0,i).some(long=>long.includes(n)))}
function parseAbility(text){const matched={};for(const k of ['pokemon','items','abilities','moves'])matched[k]=matchText(text,k);let exact=matched.pokemon.filter(n=>row(n));let scores=stats().map(p=>({p,score:['items','abilities','moves'].reduce((a,k)=>a+matched[k].filter(n=>p[k].some(x=>x.name===n)).length,0)})).filter(x=>x.score>=2).sort((a,b)=>b.score-a.score);return {matched,candidates:exact.length?exact:scores.slice(0,8).map(x=>x.p.name),name:exact.length===1?exact[0]:''}}
function renderOcr(){$('ocrResults').innerHTML=ocr.map((o,i)=>{const p=row(o.name);return `<div class="ocrrow"><div class="sectionhead"><h3>슬롯 ${i+1} · ${o.name?esc(o.name):'포켓몬 확인 필요'}</h3>${o.name?`<button data-detail="${esc(o.name)}">상세 통계</button><button data-ocrclear="${i}">선택 해제</button>`:''}</div><div class="candidates" aria-label="슬롯 ${i+1} 인식 후보">${(o.candidates||[]).map(n=>`<button class="candidate ${o.name===n?'chosen':''}" data-ocrcandidate="${i}" data-name="${esc(n)}" aria-pressed="${o.name===n}">${esc(n)}${o.name===n?' ✓':''}</button>`).join('')||'<p>확인된 후보가 없습니다. 이름으로 검색해 주세요.</p>'}</div><label class="ocrsearchlabel">포켓몬 검색<input type="search" data-ocrquery="${i}" value="${esc(o.name)}" placeholder="예: 나인테일, 나인테일 알로라폼" autocomplete="off" aria-label="슬롯 ${i+1} 포켓몬 검색"></label><div class="ocrmatches" data-ocrmatches="${i}" aria-live="polite"></div><div class="ocrfields">${searchChoice(p||{name:''},'items',`ocr-${i}-items`,o.items,'도구',`data-ocrfield="items" data-ocrslot="${i}"`)}${searchChoice(p||{name:''},'abilities',`ocr-${i}-abilities`,o.abilities,'특성',`data-ocrfield="abilities" data-ocrslot="${i}"`)}${searchChoice(p||{name:''},'natures',`ocr-${i}-natures`,o.natures,'성격',`data-ocrfield="natures" data-ocrslot="${i}"`)}<div class="ocrmoves">${[0,1,2,3].map(j=>searchChoice(p||{name:''},'moves',`ocr-${i}-move-${j}`,o.moves[j]||'',`기술 ${j+1}`,`data-ocrmove="${j}" data-ocrslot="${i}"`)).join('')}</div></div>${o.fallback?.length?`<p class="ocrfallback">통계 보완: ${esc(o.fallback.join(', '))} · 인식되지 않은 값은 해당 모드 최상위 채용 세팅을 사용했습니다.</p>`:''}<div class="statgrid">${'HABCDS'.split('').map((k,j)=>`<label>${k}<input type="number" min="0" max="32" step="1" data-ocrslot="${i}" data-ocrstat="${j}" value="${o.evs[j]??''}" placeholder="—"></label>`).join('')}</div><p data-ocrsum="${i}">합계 ${sum(o.evs)} / 66 ${o.evs.some(v=>v===null)?'· 미확인 값 있음':''}</p><details><summary>인식 원문 확인 / 수정</summary><textarea data-raw="${i}" aria-label="슬롯 ${i+1} 능력 인식 원문">${esc(o.raw)}</textarea>${o.statsRaw?'<p>스테이터스 인식 원문</p><pre style="white-space:pre-wrap;font-size:12px">'+esc(o.statsRaw)+'</pre>':''}<button data-reparse="${i}">수정 원문 다시 반영</button></details></div>`}).join('')}
function setOcrName(i,n){ocr[i]=selectOcrSpecies(ocr[i],row(n)?n:'')}
$('ocrResults').addEventListener('change',e=>{if(e.target.dataset.ocrname!==undefined){setOcrName(+e.target.dataset.ocrname,e.target.value);renderOcr()}if(e.target.dataset.ocrstat!==undefined){const o=ocr[+e.target.dataset.ocrslot];o.evs[+e.target.dataset.ocrstat]=e.target.value===''?null:Number(e.target.value);document.querySelector('[data-ocrsum="'+e.target.dataset.ocrslot+'"]').textContent='합계 '+sum(o.evs)+' / 66'+(o.evs.some(v=>v===null)?' · 미확인 값 있음':validEV(o.evs)?' ✓':' · 범위 초과')}if(e.target.dataset.ocrfield){ocr[+e.target.dataset.ocrslot][e.target.dataset.ocrfield]=e.target.value.trim()}if(e.target.dataset.ocrmove!==undefined){const o=ocr[+e.target.dataset.ocrslot],j=+e.target.dataset.ocrmove;o.moves[j]=e.target.value.trim();/* Keep blank move positions until apply. */}});
$('ocrResults').addEventListener('click',e=>{const b=e.target.closest('[data-reparse]');if(!b)return;const i=+b.dataset.reparse,text=document.querySelector(`[data-raw="${i}"]`).value,p=parseAbility(text);ocr[i]=applyEditedRecognitionText(ocr[i],{...p,name:p.name||ocr[i].name,raw:text});setOcrName(i,ocr[i].name);renderOcr()});
let previewURLs=[],ocrBusy=false;
const imageOk=f=>f&&f.size<=15*1024*1024&&/^image\/(png|jpeg|webp)$/.test(f.type);
function openImage(src){$('imageViewerImg').src=src;$('imageViewer').showModal()}
function renderUploads(){let gallery=$('uploadGallery');if(!gallery){gallery=document.createElement('div');gallery.id='uploadGallery';gallery.className='uploadgallery';$('preview').replaceWith(gallery)}gallery.innerHTML=previewURLs.map((u,i)=>`<figure><button class="imagezoom" data-imagezoom="${i}" aria-label="${i+1}번째 이미지 크게 보기"><img src="${u}" alt="업로드 이미지 ${i+1}"></button><button class="imageremove" data-imageremove="${i}">삭제</button></figure>`).join('');$('ocrBtn').disabled=!imageFiles.length;$('ocrStatus').textContent=imageFiles.length?`${imageFiles.length}장 선택됨 · 화면 종류를 자동 판별합니다.`:'이미지를 선택하거나 이 영역에 끌어다 놓으세요.'}
async function setOcrFiles(files){if(ocrBusy)return;const next=[...files];if(!next.length)return;if(next.some(f=>!imageOk(f)))return toast('각 파일은 15MB 이하 PNG, JPG, WebP여야 합니다.');previewURLs.forEach(u=>URL.revokeObjectURL(u));imageFiles=next;previewURLs=next.map(f=>URL.createObjectURL(f));renderUploads();await runAIRecognition()}
