const mainDrop=$('imageFile').closest('.dropzone');for(const type of ['dragenter','dragover'])mainDrop.addEventListener(type,e=>{e.preventDefault();mainDrop.classList.add('dragging')});for(const type of ['dragleave','drop'])mainDrop.addEventListener(type,e=>{e.preventDefault();mainDrop.classList.remove('dragging')});mainDrop.addEventListener('drop',e=>setOcrFiles(e.dataTransfer.files));
document.querySelector('#import').addEventListener('click',e=>{const zoom=e.target.closest('[data-imagezoom]'),remove=e.target.closest('[data-imageremove]');if(zoom)return openImage(previewURLs[+zoom.dataset.imagezoom]);if(remove){const i=+remove.dataset.imageremove;URL.revokeObjectURL(previewURLs[i]);imageFiles.splice(i,1);previewURLs.splice(i,1);renderUploads()}});

async function runAIRecognition(allowAI=false){if(!imageFiles.length||ocrBusy)return;ocrBusy=true;for(const id of ['ocrBtn','applyOcr','imageFile','single','double'])$(id).disabled=true;
try{$('ocrStatus').textContent='원본 글자와 능력치 6개를 로컬에서 검증합니다…';const references=await officialIconReferences(),localResults=await Promise.all(imageFiles.map(file=>recognizeFileLocally(file,'party',references)));const partyCandidates=Array.from({length:6},(_,i)=>localResults.map(value=>value.slots[i]).find(value=>value.name)||localResults[0].slots[i]);const result=await recognizeImages({files:imageFiles,mode,kind:'party',partyCandidates,allowAI});const localSlots=result.slots.map((_,i)=>localResults.map(value=>value.slots[i]).find(value=>value.name)||localResults[0].slots[i]);const merged=mergePartyRecognition(result.slots,localSlots,name=>Boolean(row(name)));for(const slot of merged){const i=slot.slot-1,o=ocr[i],name=slot.name;o.matched={pokemon:name?[name]:[],items:slot.item?[slot.item]:[],abilities:slot.ability?[slot.ability]:[],moves:slot.moves};o.candidates=slot.candidates;o.evs=slot.evs;o.natures=slot.nature;o.raw=JSON.stringify(slot,null,2);o.name=name;o.fallback=[];o.items='';o.abilities='';o.natures='';o.moves=[];{const allowed=k=>new Set(D.master[k].map(x=>x[0]));if(allowed('items').has(slot.item))o.items=slot.item;if(allowed('abilities').has(slot.ability))o.abilities=slot.ability;if(allowed('natures').has(slot.nature))o.natures=slot.nature;o.moves=slot.moves.map(n=>allowed('moves').has(n)?n:'').slice(0,4);o.evs=slot.evs}if(slot.notes)o.raw+='\n\n'+slot.notes}renderOcr();const named=ocr.filter(o=>o.name).length;$('ocrStatus').textContent=`${result.source==='local'?'로컬':'AI 보조'} 인식 완료 · ${named}/6마리 확인${result.source==='local'?' · AI 호출 없음':''} · 각 값을 검토한 뒤 적용하세요.`
}catch(e){$('ocrStatus').textContent=e.message||'AI 이미지 인식에 실패했습니다.'}finally{ocrBusy=false;for(const id of ['ocrBtn','applyOcr','imageFile','single','double'])$(id).disabled=false}}
$('ocrBtn').onclick=()=>runAIRecognition(true);
$('applyOcr').onclick=()=>{let next=team().map(x=>x?structuredClone(x):null),count=0;for(let i=0;i<6;i++){const o=ocr[i];if(!o.name)continue;const p=row(o.name);if(!p)return toast(`슬롯 ${i+1}: 현재 모드에 통계가 없습니다.`);let s;try{s=partySetFromRecognition(o)}catch(error){return toast(`슬롯 ${i+1}: ${error.message}`)}if(!validSet(s))return toast(`슬롯 ${i+1}: 챔피언스 전체 목록의 정확한 공식 한글 명칭과 배분을 확인해 주세요.`);next[i]=s;count++}if(!count)return toast('적용할 포켓몬을 선택해 주세요.');let names=next.filter(Boolean).map(x=>x.name);if(new Set(names).size!==names.length)return toast('동일한 포켓몬이 중복되어 있습니다. 슬롯을 확인해 주세요.');teams[mode]=next;persist();render();toast(`${count}개 슬롯을 적용했습니다.`)};

const TYPE_COLORS={노말:[168,167,122],불꽃:[238,129,48],물:[99,144,240],전기:[247,208,44],풀:[122,199,76],얼음:[150,217,214],격투:[194,46,40],독:[163,62,161],땅:[226,191,101],비행:[169,143,243],에스퍼:[249,85,135],벌레:[166,185,26],바위:[182,161,54],고스트:[115,87,151],드래곤:[111,53,252],악:[112,87,70],강철:[183,183,206],페어리:[214,133,173]};
function loadImage(src){return new Promise((resolve,reject)=>{const img=new Image;img.onload=()=>resolve(img);img.onerror=reject;img.src=src})}
function plainCrop(img,x,y,w,h,size=72){x=Math.max(0,x);y=Math.max(0,y);w=Math.max(1,Math.min(w,img.width-x));h=Math.max(1,Math.min(h,img.height-y));const c=document.createElement('canvas'),ratio=w/h;c.width=size;c.height=Math.max(36,Math.round(size/ratio));c.getContext('2d').drawImage(img,x,y,w,h,0,0,c.width,c.height);return c}
const learnedKey='champions-recognition-v1';
function learnedReferences(){try{return JSON.parse(localStorage.getItem(learnedKey)||'[]').filter(x=>x&&row(x.name)&&validVisualFeature(x.feature))}catch{return[]}}
function saveLearnedReferences(entries){const old=learnedReferences(),next=[...old];for(const entry of entries){const same=next.map((x,i)=>({x,i})).filter(({x})=>x.name===entry.name&&x.side===entry.side);while(same.length>=4){next.splice(same.shift().i,1);for(const s of same)s.i--}next.push({...entry,feature:compactFeature(entry.feature),source:'사용자 확인'})}try{localStorage.setItem(learnedKey,JSON.stringify(next.slice(-120)))}catch{return false}spriteFeaturePromise=null;return true}
