document.querySelectorAll('dialog').forEach(dialog=>dialog.addEventListener('click',e=>{if(e.target!==dialog)return;const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}));
function showDetails(name){const p=row(name),base=master(name);$('detailTitle').textContent=name+' · 상세 통계';if(!base){$('detailBody').innerHTML='<p>첨부 데이터에 해당 정보가 없습니다.</p>';$('details').showModal();return}const src=O?.modes[mode],freq=src?.frequency.find(x=>x.name===name);let head=`<div class="detailhero">${monSprite(name,'detail')}<div><strong>${esc(name)}</strong><p>${esc(base[2])} · 상세 통계 ${D.date} · ${mode==='single'?'싱글':'더블'} ${p?p.rank+'위':'통계 없음'}</p></div></div><div class="basestats">${['HP','공격','방어','특공','특방','스피드'].map((l,i)=>`<div><small>${l}</small><strong>${base[i+3]}</strong></div>`).join('')}</div><p>${freq?'공개 상위 파티 표본: '+freq.rate+'% ('+freq.count+'/'+src.count+'개 파티)':'공개 상위 파티 표본에 등재되지 않음'} · 전체 랭크배틀 사용률 아님</p>`;if(p){const table=(key,label)=>`<section class="statsection"><h3>${label}</h3><table><thead><tr><th>선택</th><th>항목</th><th>채용률</th></tr></thead><tbody>${p[key].map((v,i)=>{const m=D.master[key]?.find(x=>x[0]===v.name);let extra=key==='evs'?'합계 '+sum(evparse(v.name))+' ✓':key==='moves'&&m?(koreanType[m[2]]||m[2])+' / '+m[3]+' / 위력 '+m[4]+' / 명중 '+m[5]:key==='items'||key==='abilities'?m?.[2]||'':key==='natures'&&m?'상승 '+m[2]+' / 하락 '+m[3]:'';const control=key==='moves'?`<input type="checkbox" name="detail-moves" value="${esc(v.name)}" ${i<4?'checked':''} aria-label="${esc(v.name)} 선택">`:`<input type="radio" name="detail-${key}" value="${esc(v.name)}" ${i===0?'checked':''} aria-label="${esc(v.name)} 선택">`;return `<tr><td>${control}</td><td>${esc(v.name)}<small>${esc(extra)}</small></td><td>${v.rate}%</td></tr>`}).join('')||'<tr><td colspan="3">확인된 항목 없음</td></tr>'}</tbody></table></section>`;head+=`<div class="detailactions"><button class="primary" data-detailbuild="${esc(name)}">선택한 통계 구성 적용</button><button data-detailcustom="${esc(name)}">전체 목록에서 직접 설정</button></div><p class="detailnotice">기술은 최대 4개를 선택하세요. 각 채용률은 독립 집계이므로 이 조합 전체의 동시 채용률은 아닙니다.</p><div class="detailstats">${[['moves','기술'],['items','도구'],['abilities','특성'],['natures','성격'],['evs','능력 배분']].map(([k,l])=>table(k,l)).join('')}</div><section class="statsection"><h3>팀메이트</h3><div class="candidates">${p.teammates.map(n=>`<button data-detail="${esc(n)}">${esc(n)}</button>`).join('')||'첨부 데이터 없음'}</div></section><section class="statsection"><h3>이 포켓몬을 쓰러뜨린 상대</h3><p>원본의 쓰러뜨린 포켓몬 통계이며, 팀메이트 추천과 파티 점검의 실전 대응 근거로 사용합니다.</p>${p.counters.map(c=>`<p><button class="monlink" data-detail="${esc(c.name)}">${esc(c.name)}</button> · 승률 ${c.rate}% · 표본 ${c.n}</p>`).join('')||'<p>원본에 해당 통계 없음</p>'}</section>`}head+='<p>상세 통계 미등재 항목은 직접 설정에서 챔피언스 전체 마스터 목록으로 선택할 수 있습니다. 기술·특성의 포켓몬별 사용 가능 여부는 현재 자료에 없으므로 직접 확인해야 합니다.</p>';$('detailBody').innerHTML=head;if(!$('details').open)$('details').showModal();$('details').scrollTop=0}
function dexInfoHtml(name,p,base){const d=pokedexDetails({master:base,row:p,abilities:D.master.abilities,typeMultiplier:multiplier}),labels=['HP','공격','방어','특공','특방','스피드'],typed=values=>values.map(([type,value])=>type+(value===0?' 무효':' ×'+value)).join(' · ')||'없음';return `<section class="statsection pokedex-info"><h3>도감 기본정보</h3><p>키 미제공 · 몸무게 미제공</p><div class="dex-stat-bars">${d.stats.map((value,index)=>`<div><small>${labels[index]}</small><span><i style="width:${Math.min(100,value/2)}%"></i></span><b>${value}</b></div>`).join('')}</div><p><b>종족값 합계 ${d.total}</b></p><h3>특성</h3>${d.abilities.length?d.abilities.map(item=>`<p><b>${esc(item.name)}</b> — ${esc(item.description||'설명 미제공')}</p>`).join(''):'<p>동시즌 특성 미제공</p>'}<h3>타입 상성 요약</h3><p><b>공격 범위:</b> ${esc(d.offense.join(' · ')||'없음')}</p><p><b>방어 약점:</b> ${esc(typed(d.weak))}<br><b>반감·무효:</b> ${esc(typed(d.resist))}</p></section>`}
const showDetailsWithSettings=showDetails;
showDetails=name=>{const p=row(name),base=master(name);if(p?.settingsAvailable!==false){showDetailsWithSettings(name);$('detailBody').insertAdjacentHTML('beforeend',dexInfoHtml(name,p,base));return}$('detailTitle').textContent=name+' · 상세 통계';$('detailBody').innerHTML=`<div class="detailhero">${monSprite(name,'detail')}<div><strong>${esc(name)}</strong><p>${esc(base?.[2]||p.types.join(' / '))} · ${esc(selectedSeason())} · ${mode==='single'?'싱글':'더블'} ${Number.isFinite(p.rank)?p.rank+'위':'순위 미등재'}</p></div></div>${dexInfoHtml(name,p,base)}<section class="statsection"><h3>세팅 미제공</h3><p>${esc(selectedSeason())} 순위와 종족값·타입·이미지는 확인됐지만, 같은 시즌의 기술·도구·특성·성격·능력 배분은 제공되지 않았습니다. 이전 시즌 세팅을 대신 보여주지 않습니다.</p><button data-add="${esc(name)}">세팅 없이 파티에 추가</button></section>`;if(!$('details').open)$('details').showModal();$('details').scrollTop=0};
$('detailBody').addEventListener('change',e=>{if(e.target.name!=='detail-moves'||!e.target.checked)return;const selected=$('detailBody').querySelectorAll('input[name="detail-moves"]:checked');if(selected.length>4){e.target.checked=false;toast('기술은 최대 4개까지 선택할 수 있습니다.')}});
$('detailBody').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.detailcustom){const name=b.dataset.detailcustom,target=team().findIndex(x=>x?.name===name);$('details').close();edit(target,name)}if(b.dataset.detailbuild){const name=b.dataset.detailbuild,p=row(name),pick=k=>$('detailBody').querySelector(`input[name="detail-${k}"]:checked`)?.value||'',moves=[...$('detailBody').querySelectorAll('input[name="detail-moves"]:checked')].map(x=>x.value),evs=evparse(pick('evs')),s={name,items:pick('items'),abilities:pick('abilities'),natures:pick('natures'),moves,evs};if(!validSet(s))return toast('도구·특성·성격·배분과 기술 1~4개를 선택해 주세요.');let target=team().findIndex(x=>x?.name===name);if(target<0)target=team().indexOf(null);if(target<0)return toast('파티가 가득 찼습니다. 먼저 한 자리를 비워 주세요.');team()[target]=s;persist();render();$('details').close();toast(`${name}의 선택한 통계 구성을 파티에 적용했습니다.`)}});
$('sourceBtn').addEventListener('click',()=>{$('sourceBody').insertAdjacentHTML('beforeend','<p><b>이미지 인식 참조:</b> 현재 모드 리스팅 235종만 후보로 사용합니다. 사용자 제공 챔피언스 화면의 확정 아이콘과 기기에서 사용자가 확정한 화면 특징을 우선 비교하고, 챔피언스 아이콘을 기기 안에서 직접 비교하여 확인용 후보를 제시합니다. 타입색 추정은 후보 점수에 강제 반영하지 않습니다. 사용자 요청에 따라 공개 이미지 원본을 개인 사용용 로컬 DB로 보관합니다. 배포는 하지 않았으며 원본 이미지의 권리는 각 권리자에게 있습니다. 이미지 자료는 포켓몬·기술·도구·특성·메타 데이터에 사용하지 않습니다.</p>')});
